const err = $input.first()?.json || {};
const exec = err.execution || {};
const wf = err.workflow || {};
const lastNode = (err.execution && err.execution.lastNodeExecuted) || (err.execution && err.execution.error && err.execution.error.node && err.execution.error.node.name) || null;
const msg = (err.execution && err.execution.error && err.execution.error.message) || 'Unknown workflow error';
return [{ json: {
  workflow_id: wf.id || null,
  workflow_name: wf.name || null,
  execution_id: exec.id || null,
  execution_url: exec.url || null,
  failed_node: lastNode,
  error_message: String(msg).slice(0, 1000),
  logged_at: new Date().toISOString(),
  source: 'n8n-error-trigger'
} }];
